import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/registry/erbium/ui/carousel";

const CarouselSpacing = () => (
  <Carousel className="w-full max-w-sm">
    <CarouselContent className="-ml-1">
      {Array.from({ length: 5 }).map((_, index) => (
        <CarouselItem key={index} className="pl-1 md:basis-1/2 lg:basis-1/3">
          <div className="p-1">
            <Card className="aspect-square">
              <CardContent className="flex min-h-0 flex-1 items-center justify-center">
                <span className="text-title font-semibold">{index + 1}</span>
              </CardContent>
            </Card>
          </div>
        </CarouselItem>
      ))}
    </CarouselContent>
    <CarouselPrevious />
    <CarouselNext />
  </Carousel>
);

export default CarouselSpacing;

import ExampleCarouselSpacing from "../examples/carousel-spacing";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleCarouselSpacing />
  </div>
);

export default Example;
